import { ed25519 } from '@noble/curves/ed25519.js';
import { encodeCanonical } from '../../../src/v2/cbor.js';
import { authorizationChallenge } from '../../../src/v2/identifiers.js';
import { checkedUint128Add, validateTransaction, validateUniqueOutputIds, V2ValidationError } from '../../../src/v2/validator.js';
import type { MintNote, Transaction, TxOutput } from '../../../src/v2/models.js';

const bytes = (value: number, length = 32) => new Uint8Array(length).fill(value);
const opaque = new Uint8Array([1]);
const domain = bytes(3); const asset = bytes(4); const ownerSecret = bytes(42); const ownerPublic = ed25519.getPublicKey(ownerSecret);
const note = (amount: number, id: number): MintNote => ({ kind: 'mint', asset_id: asset, amount, recipient_key: ownerPublic, spend_domain: domain, output_commitment: bytes(6), output_id: bytes(id), issued_at: 1, expires_at: 100, mint_transaction_id: bytes(7), output_index: 0, keyset_id: bytes(8), mint_credential: { kind: 'mint', keyset_id: bytes(8), credential_payload: { keyset_id: bytes(8), asset_id: asset, spend_domain: domain, denomination: amount, issuance_epoch: 0, expiry_epoch: 1, blinded_payload: { owner_material: ownerPublic, replay_nonce: bytes(10) } }, signature_envelope: opaque } });
const output = (amount: number, id: number, assetId = asset): TxOutput => ({ asset_id: assetId, amount, recipient_key: bytes(9 + id), spend_domain: domain, output_commitment: bytes(20 + id), provenance: { kind: 'transition' } });
const transaction = (): Transaction => { const input = { note: note(10, 1), nullifier: new Uint8Array(32), authorization_ref: 0 }; const tx: Transaction = { spend_domain: domain, inputs: [input], outputs: [output(4, 1), output(6, 2)], authorizations: [{ input_index: 0, owner_key_id: bytes(0), challenge: bytes(1), signature: new Uint8Array(64) }] }; return tx; };
const signAuthorizations = (tx: Transaction) => { const core = { spend_domain: tx.spend_domain, inputs: tx.inputs.map((input) => ({ output_id: input.note.output_id, nullifier: input.nullifier, owner_key_id: v2Hash('owner-key', (input.note as MintNote).recipient_key) })), outputs: tx.outputs }; const digest = v2Hash('transaction', encodeCanonical(core)); tx.authorizations.forEach((auth) => { auth.owner_key_id = v2Hash('owner-key', (tx.inputs[auth.input_index].note as MintNote).recipient_key); auth.challenge = authorizationChallenge(digest, auth.input_index, tx.spend_domain, auth.owner_key_id); auth.signature = ed25519.sign(auth.challenge, ownerSecret); }); };
const valid = transaction();
// Construct the deterministic nullifier and owner id expected by the structural validator.
import { nullifier } from '../../../src/v2/identifiers.js';
import { v2Hash } from '../../../src/v2/identifiers.js';
valid.inputs[0].nullifier = nullifier(domain, valid.inputs[0].note.output_id); signAuthorizations(valid);
if (validateTransaction(valid).output_ids.length !== 2) throw new Error('valid split-like transaction rejected');
const merge: Transaction = { spend_domain: domain, inputs: [{ note: note(4, 1), nullifier: new Uint8Array(32), authorization_ref: 0 }, { note: note(6, 2), nullifier: new Uint8Array(32), authorization_ref: 1 }], outputs: [output(10, 3)], authorizations: [{ input_index: 0, owner_key_id: bytes(0), challenge: bytes(1), signature: new Uint8Array(64) }, { input_index: 1, owner_key_id: bytes(0), challenge: bytes(2), signature: new Uint8Array(64) }] };
for (const input of merge.inputs) input.nullifier = nullifier(domain, input.note.output_id); signAuthorizations(merge);
if (validateTransaction(merge).output_ids.length !== 1) throw new Error('valid merge-like transaction rejected');
const expect = (mutate: (tx: Transaction) => void, category: string) => { const tx = transaction(); tx.inputs[0].nullifier = nullifier(domain, tx.inputs[0].note.output_id); signAuthorizations(tx); mutate(tx); try { validateTransaction(tx); throw new Error('accepted invalid transaction'); } catch (error) { if (!(error instanceof V2ValidationError) || error.category !== category) throw error; } };
expect((tx) => { tx.outputs = []; }, 'schema'); expect((tx) => { tx.outputs[0].spend_domain = bytes(99); }, 'schema'); expect((tx) => { tx.outputs[0].amount = 0; }, 'arithmetic'); expect((tx) => { tx.outputs[0].asset_id = bytes(99); }, 'arithmetic'); expect((tx) => { tx.inputs[0].nullifier = bytes(55); }, 'nullifier'); expect((tx) => { tx.authorizations = []; }, 'authorization'); expect((tx) => { tx.authorizations[0].signature = new Uint8Array(63); }, 'schema'); expect((tx) => { tx.inputs[0].note.output_id = bytes(2, 31); }, 'schema'); expect((tx) => { (tx.inputs[0].note as MintNote).mint_credential.credential_payload.blinded_payload.owner_material = new Uint8Array(); }, 'schema'); expect((tx) => { tx.outputs[0].provenance = { kind: 'mint', keyset_id: bytes(1, 31), credential_payload: { keyset_id: bytes(1, 31), asset_id: asset, spend_domain: domain, denomination: 1, issuance_epoch: 0, expiry_epoch: 1, blinded_payload: { owner_material: ownerPublic, replay_nonce: bytes(10) } }, signature_envelope: opaque }; }, 'schema'); expect((tx) => { (tx.inputs[0].note as MintNote).amount = 10; tx.outputs[0].amount = 9; }, 'arithmetic'); expect((tx) => { (tx.inputs[0].note as MintNote).amount = (1n << 64n); }, 'arithmetic');
const expectMerge = (mutate: (tx: Transaction) => void, category: string) => { const tx: Transaction = structuredClone(merge); tx.inputs = merge.inputs.map((input) => ({ ...input, note: { ...input.note } })); tx.authorizations = merge.authorizations.map((authorization) => ({ ...authorization })); for (const input of tx.inputs) input.nullifier = nullifier(domain, (input.note as MintNote).output_id); signAuthorizations(tx); mutate(tx); try { validateTransaction(tx); throw new Error('accepted invalid merge'); } catch (error) { if (!(error instanceof V2ValidationError) || error.category !== category) throw error; } };
expectMerge((tx) => { tx.inputs.reverse(); }, 'schema'); expectMerge((tx) => { tx.inputs[1].note.output_id = tx.inputs[0].note.output_id; }, 'schema'); expectMerge((tx) => { tx.inputs[1].nullifier = tx.inputs[0].nullifier; }, 'nullifier'); expectMerge((tx) => { (tx.inputs[0].note as MintNote).spend_domain = bytes(77); }, 'schema'); expectMerge((tx) => { tx.inputs[1].authorization_ref = 0; }, 'authorization');
try { checkedUint128Add((1n << 128n) - 1n, 1n); throw new Error('uint128 overflow accepted'); } catch (error) { if (!(error instanceof V2ValidationError) || error.category !== 'arithmetic') throw error; }
try { validateUniqueOutputIds([bytes(1), bytes(1)]); throw new Error('duplicate output id accepted'); } catch (error) { if (!(error instanceof V2ValidationError) || error.category !== 'schema') throw error; }
console.log('V2 Phase 1B structural/conservation tests: passed');
